using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;
sealed partial class WorldWindow {
 readonly object userTemplateLock=new object();
 async Task HandleUserTemplates(Dictionary<string,object> m){string request=Convert.ToString(m["request"]);try{var result=await Task.Run(()=>{lock(userTemplateLock){string rawType=Convert.ToString(m["type"]);bool brand=rawType.StartsWith("project-brand-",StringComparison.Ordinal);string dir=Path.Combine(Program.Root,brand?"Brand-kits":"Templates");Directory.CreateDirectory(dir);string type=rawType.Replace("project-brand-","project-template-");if(type=="project-template-list"){var items=new List<object>();foreach(var file in new DirectoryInfo(dir).GetFiles("*.jagotemplate").OrderByDescending(f=>f.LastWriteTimeUtc).Take(60)){try{if(file.Length>45000000)continue;var t=ProjectSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(File.Exists(file.FullName+".meta")?file.FullName+".meta":file.FullName));items.Add(new{id=Path.GetFileNameWithoutExtension(file.Name),name=t["name"],category=t["category"],thumbnail=t["thumbnail"],colours=t.ContainsKey("colours")?t["colours"]:new object[0],folder=t.ContainsKey("folder")?t["folder"]:"",references=t.ContainsKey("references")?t["references"]:new object[0],updated=new DateTimeOffset(file.LastWriteTimeUtc).ToUnixTimeMilliseconds()});}catch{}}return (object)new{type="project-result",request,items};}
 Guid parsed;string id=Convert.ToString(m["id"]);if(!Guid.TryParseExact(id,"D",out parsed))throw new InvalidDataException("Invalid template identity.");string path=Path.Combine(dir,id+".jagotemplate");if(type=="project-template-read"){var f=new FileInfo(path);if(!f.Exists||f.Length>45000000)throw new IOException("Template unavailable or oversized.");return new{type="project-result",request,json=File.ReadAllText(path)};}
 if(type=="project-template-delete"){if(File.Exists(path))File.Delete(path);if(File.Exists(path+".meta"))File.Delete(path+".meta");return new{type="project-result",request,deleted=true};}
 if(type=="project-template-save"){string json=Convert.ToString(m["json"]);if(json.Length>45000000)throw new IOException("Save a template under 45 MB.");var t=ProjectSerializer().Deserialize<Dictionary<string,object>>(json);if(Convert.ToString(t["format"])!="jago-library-template"||Convert.ToInt32(t["version"])!=1||Convert.ToString(t["id"])!=id)throw new InvalidDataException("Unsupported template.");var files=new DirectoryInfo(dir).GetFiles("*.jagotemplate");if(!File.Exists(path)&&files.Length>=60)throw new IOException("Your shelf holds 60 templates. Remove one before adding another.");if(files.Where(f=>f.FullName!=path).Sum(f=>f.Length)+System.Text.Encoding.UTF8.GetByteCount(json)>256000000)throw new IOException("Template shelf exceeds 256 MB. Export and remove unused templates first.");string temp=Path.Combine(dir,".template-"+Guid.NewGuid().ToString("N")+".tmp");try{File.WriteAllText(temp,json,new System.Text.UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}try{File.WriteAllText(path+".meta",ProjectSerializer().Serialize(new{id,name=t["name"],category=t["category"],thumbnail=t["thumbnail"],colours=t.ContainsKey("colours")?t["colours"]:new object[0],folder=t.ContainsKey("folder")?t["folder"]:"",references=t.ContainsKey("references")?t["references"]:new object[0]}),new System.Text.UTF8Encoding(false));}catch{if(File.Exists(path+".meta"))File.Delete(path+".meta");}return new{type="project-result",request,saved=true};}throw new InvalidOperationException("Unsupported template action.");}});ManagedPost(result);}catch(Exception e){ManagedPost(new{type="project-result",request,error=e.Message});}}
}
